insert into public.events (title, description, active) values
('A leves a billentyűzetben landol', 'Az első kanálnál meglököd a tányért. A laptopod még egyszer felvillan, majd nagyon csendes lesz.', true),
('Néma prezentáció', 'Tíz perce beszélsz lelkesen az online megbeszélésen, amikor valaki jelzi, hogy végig le voltál némítva.', true),
('A rossz csoport', 'A főnöködről szóló panaszüzenetet nem a barátodnak, hanem a munkahelyi közös beszélgetésbe küldöd.', true),
('Bőröndöd külön nyaral', 'Te megérkeztél a tengerpartra, a poggyászod egy havas északi városba. A légitársaság három nap múlva jelentkezik.', true),
('Kulcs a túloldalon', 'A huzat becsapja az ajtót. Te a folyosón állsz papucsban, a telefonod és a kulcsod bent maradt.', true),
('Automata borravaló', 'A fizetési terminálon véletlenül egy nullával nagyobb borravalót hagysz. A pincér már könnyes szemmel köszöngeti.', true),
('A torta megérkezett', 'A születésnapi tortával az ajtóban elbotlasz. A gyertyák túlélik, a torta nem.', true),
('Nyomtató az utolsó percben', 'A fontos iratot indulás előtt nyomtatnád ki. A gép szerint kifogyott a cián, pedig az egész dokumentum fekete-fehér.', true),
('Hazafelé nincs járat', 'Az utolsó busz az orrod előtt kanyarodik ki. A következő reggel indul, a taxira pedig ma költötted el a pénzed.', true),
('A szomszéd új hobbija', 'A feletted lakó nyugdíjas dobfelszerelést vesz. Kiderül, hogy hajnalban a legkreatívabb.', true),
('Közös képernyő, privát keresés', 'Megosztod a böngésződet a kollégákkal, és a kereső felajánlja a tegnap esti, meglehetősen kínos kérdésedet.', true),
('Csípős meglepetés', 'A rendelésedre véletlenül dupla erős szósz kerül. Csak az első nagy falat után derül ki, és nincs más ebéded.', true),
('Elázott sátor', 'A kemping első éjszakáján kiderül, hogy a sátor vízállósága inkább optimista elképzelés. A hálózsákod is úszik.', true),
('Valaki már lakik a szálláson', 'Éjjel érkezel a lefoglalt apartmanhoz. Az ajtót egy család nyitja ki, akik ugyanazt a lakást foglalták le.', true),
('A nadrág feladja', 'Lehajolsz egy ünnepségen a kabátodért. A nadrágod hátul hangos, egyértelmű nyilatkozatot tesz.', true),
('Kétszer fizetett nyaralás', 'Lemondod az utazást egy fontos munka miatt. A lemondás nem visszatéríthető, a munkát másnap törlik.', true),
('A felhő sem mentett', 'Eltűnik a hetek óta készülő dolgozatod. Kiderül, hogy a biztonsági mentés pont azt a mappát nem tartalmazta.', true),
('Elfogy a benzin', 'Az autó az országút szélén áll meg. A műszer szerint még húsz kilométert mehettél volna, a legközelebbi kút viszont harmincra van.', true),
('Végtelen ügyfélszolgálat', 'Ötven perc várakozás után kapcsolnak. Az ügyintéző első mondata közben lemerül a telefonod.', true),
('Meglepetés a cipőben', 'Sietve belelépsz a cipődbe. A macska egy friss, személyes véleményt hagyott benne.', true),
('Az exed az új szomszéd', 'Az új lakásod tökéletesnek tűnik, amíg a melletted lévő ajtón nem az exed és az új párja lép ki.', true),
('Az interjú egy órával korábban volt', 'Öltönyben, felkészülten érkezel. A naptárad más időzónában mutatta az állásinterjút.', true),
('Frissen festve', 'Leülsz a park legszebb padjára. Felálláskor meglátod a táblát, és megérted, miért olyan ragyogó a zöld szín.', true),
('Egy jegy, rossz hónap', 'A koncert bejáratánál derül ki, hogy a jegyed ugyanarra a napra szól, csak a múlt hónapban volt érvényes.', true),
('A robotporszívó műalkotása', 'A kutya balesetét a robotporszívó hamarabb találja meg, mint te. A lakás egészén végigvitte a témát.', true),
('A liftben maradsz', 'Két emelet között megáll a lift. Nem vagy veszélyben, de egy nagyon beszédes idegennel vársz másfél órát.', true),
('A csomagod kézbesítve', 'A futár szerint átvetted a drága rendelésedet. A bizonyító fotón egy olyan ajtó látható, amelyet még sosem láttál.', true),
('Ébresztő néma üzemmódban', 'Átalszod az egyetlen reggelt, amikor időben kellett volna kelned. A csapat már a reptéren vár rád.', true),
('Lefolyó lett a fülbevalóból', 'Az ajándékba kapott kedvenc fülbevalód a mosdóba esik. Egyetlen kecses mozdulattal pont a lefolyóba segíted.', true),
('Különleges családi bemutatkozás', 'Először találkozol a párod szüleivel. Az általad vitt házi süteménybe só került cukor helyett.', true),
('Éjjeli lakásriasztó', 'A szomszéd riasztója félpercenként megszólal. A szomszéd két hétre elutazott, a közös képviselő nem veszi fel.', true),
('Kávé a fehér ingen', 'Az esküvő előtt öt perccel az ingedre öntöd a kávét. Te vagy a tanú, tartalék ruhát pedig nem hoztál.', true),
('A hűtő szabadságra ment', 'Egy hosszú hétvége után érkezel haza. Az elromlott hűtő tartalma már az előszobában üdvözöl.', true),
('A varázslatos automatikus javítás', 'Egy kedves üzleti üzenetet küldesz. A telefon egyetlen szót kicserél, amitől az egész nagyon sértővé válik.', true),
('Telefon a tó fenekén', 'Lefotóznád a naplementét a stégről. A telefonod még a kép elkészülte előtt közelebbről is megnézi a vizet.', true),
('Fogfájás hosszú hétvégén', 'Péntek este kezd lüktetni a fogad. A környéken csak egy ügyelet van, kétórányi utazásra.', true),
('Kéretlen közös ebéd', 'Valaki megeszi a gondosan elcsomagolt munkahelyi ebédedet. A dobozt elmosatlanul visszateszi a neveddel ellátott zacskóba.', true),
('Rossz irányba gyorsvonattal', 'Kényelmesen elhelyezkedsz a vonaton, majd észreveszed, hogy az ellenkező irányba indult. A következő megálló hetven kilométerre van.', true),
('Elromlott a mosógép', 'A mosógép lezárja az ajtót, tele vízzel és az összes tiszta munkaruháddal. A szerelő jövő hétre tud időpontot adni.', true),
('A lakbér duplázik', 'A tulajdonos közli az új lakbért. A fizetésed nem követi ezt a kreatív fejlődést, költözésre egy hónapod van.', true),
('A beszéd már az éterben', 'Azt hiszed, vége az élő adásnak, és őszintén elmondod, mit gondolsz a műsorról. A mikrofonod még működik.', true),
('A mosogatógép habpartija', 'Elfogyott a gépi tabletta, ezért kézi mosogatószert teszel a gépbe. A konyha lassan felhővé változik.', true),
('A sikeres parkolás', 'Végre találsz helyet a belvárosban. Két óra múlva az autód helyén egy autómentő cég telefonszámát találod.', true),
('A kedvenc könyved új vége', 'Hónapok óta vársz a krimi befejezésére. Egy ismerős a villamoson köszönés helyett elárulja a gyilkos nevét.', true),
('A hajvágás művészi lett', 'A fodrász szerint modern, bátor frizurát kaptál. Holnap készül a személyi igazolványod új fényképe.', true),
('Találkozó rossz étteremben', 'Egy órája várod a randipartneredet. Ő is egy órája vár, ugyanilyen nevű étteremben, a város másik végén.', true),
('Egy csavar kimaradt', 'Öt óra alatt összerakod az új szekrényt. Az utolsó oldalból kiderül, hogy a hátlapnak végig elöl kellett volna lennie.', true),
('Nincs több meleg víz', 'A zuhany akkor vált jegesre, amikor már az egész hajad samponos. A kazán kijelzőjén egy vidám hibakód villog.', true),
('Elveszett koncertfelvétel', 'Végig a telefonoddal videóztad a kedvenc dalodat. A végén látod, hogy egyszer sem indítottad el a felvételt.', true),
('A kutya és az útleveled', 'Indulás előtt a kutya büszkén hozza az útleveled maradványait. A repülő négy óra múlva indul.', true),
('Túl jó volt az ajánlat', 'Előre kifizeted az álomnyaralást egy kis utazási irodánál. Másnap az iroda ajtaján már csak a felszámolási értesítés van.', true),
('A hangüzenet folytatódott', 'Egy rövid hangüzenetet küldesz a családnak. Véletlenül a teljes, utána következő húszperces veszekedésed is rajta marad.', true),
('Az egyetlen allergiád', 'A meglepetésvacsorán minden fogásban ott van az az összetevő, amit nem ehetsz. A házigazda egész nap főzött.', true),
('Eső az erkélyen', 'A frissen mosott ágyneműt kiteszed száradni, és elmész. Hazaérve látod, hogy a felső szomszéd virágládáiból sár csöpögött rá.', true),
('A barátod kölcsönkért autója', 'Csak egy rövid útra kérted el az autót. A parkolóban egy ismeretlen végighúzta az oldalát, és nem hagyott elérhetőséget.', true),
('Éjféli rendszerfrissítés', 'A géped közvetlenül a beadási határidő előtt indul újra. A frissítés képernyője nyugodtan közli, hogy ez eltarthat egy ideig.', true),
('Mindenki tud a meglepetésről', 'Hetek óta szervezed a titkos születésnapi bulit. Az ünnepeltet is hozzáadod a szervezői beszélgetéshez.', true),
('Defekt az esőben', 'Leszakad az ég, és az autód defektet kap. A csomagtartóban megtalálod a pótkerék helyét, de kereket nem.', true),
('Az esküvői fotók eltűntek', 'A fotós memóriakártyája megsérült. A szertartásról csak egy nagynéni életlen, félig ujjal letakart képei maradtak.', true),
('A csípőpaprika utóélete', 'Erős paprikát aprítasz vacsorához, aztán reflexből megdörzsölöd a szemed. A vacsora egyelőre várhat.', true)
